package sio.la2028.database;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

final class DemoDatabase {
    private DemoDatabase() {
    }

    static void initialize(Connection connection) throws SQLException {
        try (Statement statement = connection.createStatement()) {
            statement.execute("CREATE TABLE IF NOT EXISTS pays (" +
                    "id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom VARCHAR(50) NOT NULL)");
            statement.execute("CREATE TABLE IF NOT EXISTS athlete (" +
                    "id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom VARCHAR(50) NOT NULL, " +
                    "prenom VARCHAR(50), date_naissance DATE, rang INT, pays_id INT NOT NULL, " +
                    "FOREIGN KEY (pays_id) REFERENCES pays(id))");
        }

        if (isEmpty(connection, "pays")) {
            execute(connection,
                    "INSERT INTO pays (nom) VALUES ('France')",
                    "INSERT INTO pays (nom) VALUES ('Etats-Unis')",
                    "INSERT INTO pays (nom) VALUES ('Canada')",
                    "INSERT INTO pays (nom) VALUES ('Japon')");
        }
        if (isEmpty(connection, "athlete")) {
            execute(connection,
                    "INSERT INTO athlete (nom, prenom, date_naissance, rang, pays_id) VALUES " +
                            "('Rinner', 'Jean', DATE '1995-01-01', 1, 1)",
                    "INSERT INTO athlete (nom, prenom, date_naissance, rang, pays_id) VALUES " +
                            "('Biles', 'Simone', DATE '1997-03-14', 2, 2)");
        }
    }

    private static boolean isEmpty(Connection connection, String table) throws SQLException {
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery("SELECT COUNT(*) FROM " + table)) {
            return resultSet.next() && resultSet.getInt(1) == 0;
        }
    }

    private static void execute(Connection connection, String... statements) throws SQLException {
        try (Statement statement = connection.createStatement()) {
            for (String sql : statements) {
                statement.executeUpdate(sql);
            }
        }
    }
}
